export const input={forward:0,side:0,up:0,yaw:0};const keys=new Set();export function setupControls(){const map={KeyW:['forward',1],KeyS:['forward',-1],KeyA:['side',-1],KeyD:['side',1],ArrowUp:['up',1],ArrowDown:['up',-1],ArrowLeft:['yaw',1],ArrowRight:['yaw',-1],KeyQ:['yaw',1],KeyE:['yaw',-1]};addEventListener('keydown',e=>{if(map[e.code]){keys.add(e.code);e.preventDefault()}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());for(const [id,axes] of [['left',['yaw','up']],['right',['side','forward']]]){let el=document.getElementById(id),knob=el.querySelector('.knob'),active=null;function move(e){let r=el.getBoundingClientRect(),dx=(e.clientX-r.left-r.width/2)/(r.width*.38),dy=(e.clientY-r.top-r.height/2)/(r.height*.38),l=Math.max(1,Math.hypot(dx,dy));dx/=l;dy/=l;input[axes[0]]=dx*(id==='left'?-1:1);input[axes[1]]=-dy;knob.style.left=`${50+dx*36}%`;knob.style.top=`${50+dy*36}%`}el.addEventListener('pointerdown',e=>{active=e.pointerId;el.setPointerCapture(active);move(e)});el.addEventListener('pointermove',e=>{if(active===e.pointerId)move(e)});const end=e=>{if(active!==e.pointerId)return;active=null;input[axes[0]]=input[axes[1]]=0;knob.style.left='50%';knob.style.top='50%'};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}return ()=>{const out={...input};for(const [k,[axis,v]] of Object.entries(map))if(keys.has(k))out[axis]=Math.max(-1,Math.min(1,out[axis]+v));return out}}
